1	package server
2	
3	import (
4		"crypto/rand"
5		"encoding/hex"
6		"errors"
7		"sort"
8		"sync"
9		"time"
10	)
11	
12	// Lease and admission outcomes surfaced to the HTTP layer.
13	var (
14		errNotFound             = errors.New("instance not found")
15		errLeaseConflict        = errors.New("lease conflict")
16		errHealthDisabled       = errors.New("health check disabled")
17		errInvalidHealthReport  = errors.New("invalid health report")
18		errHealthReportConflict = errors.New("health report conflict")
19		errStaleHealthReport    = errors.New("stale health report")
20		errNoRoutableInstance   = errors.New("no routable instance")
21		errConcurrencyLimited   = errors.New("concurrency limited")
22		errPermitNotFound       = errors.New("permit not found")
23	)
24	
25	// Health statuses exposed in the public instance representation.
26	const (
27		healthDisabled  = "disabled"
28		healthHealthy   = "healthy"
29		healthUnhealthy = "unhealthy"
30	)
31	
32	// healthState tracks the optional health policy of an instance and the
33	// consecutive-report counters that drive transitions. The zero value is the
34	// disabled state: no policy, no reports accepted, always routable.
35	type healthState struct {
36		configured       bool
37		failureThreshold int
38		successThreshold int
39		status           string // healthHealthy or healthUnhealthy once configured
40	
41		consecutivePass int
42		consecutiveFail int
43		lastSequence    int64
44		lastStatusPass  bool
45		hasSequence     bool
46	}
47	
48	// instance is one registered service instance plus its lease state. The
49	// exported fields are set once at registration; token and expiresAt are
50	// mutated under the registry lock.
51	type instance struct {
52		Service        string
53		Instance       string
54		Endpoint       string
55		Version        string
56		Zone           string
57		Weight         int
58		TTLSeconds     int
59		Metadata       map[string]string
60		MaxConcurrency int // zero means unbounded
61	
62		token     string
63		expiresAt time.Time
64		health    healthState
65	}
66	
67	func (i *instance) live(now time.Time) bool { return now.Before(i.expiresAt) }
68	
69	// healthStatus is the public health representation: "disabled" when no
70	// health policy was registered, otherwise the current healthy/unhealthy
71	// state driven by reported check results.
72	func (i *instance) healthStatus() string {
73		if !i.health.configured {
74			return healthDisabled
75		}
76		return i.health.status
77	}
78	
79	// permit is one outstanding short-lived admission permit. It references the
80	// exact instance record it was granted against, so overwriting,
81	// deregistering or losing the lease of that record invalidates the permit
82	// immediately even though the permit itself has not yet expired.
83	type permit struct {
84		token     string
85		service   string
86		inst      *instance
87		expiresAt time.Time
88	}
89	
90	// registry holds all live and expired-but-unpurged instances. Expiration is
91	// evaluated lazily against the caller's clock, so an expired instance can
92	// never reappear in snapshots or be revived by a stale lease token.
93	type registry struct {
94		mu        sync.Mutex
95		instances map[string]map[string]*instance // service -> instance name -> record
96		permits   map[string]*permit              // outstanding permits by opaque token
97		inUse     map[*instance]int               // unexpired permits counted per record
98	}
99	
100	func newRegistry() *registry {
101		return &registry{
102			instances: make(map[string]map[string]*instance),
103			permits:   make(map[string]*permit),
104			inUse:     make(map[*instance]int),
105		}
106	}
107	
108	// newLeaseToken mints a random opaque token. Lease and permit tokens share
109	// the shape but live in independent namespaces.
110	func newLeaseToken() string {
111		var b [16]byte
112		if _, err := rand.Read(b[:]); err != nil {
113			panic(err)
114		}
115		return hex.EncodeToString(b[:])
116	}
117	
118	// newPermitToken mints the unique opaque token identifying one permit.
119	func newPermitToken() string { return newLeaseToken() }
120	
121	// register inserts inst, replacing any previous record with the same name and
122	// minting a fresh lease token (the old token stops matching immediately). It
123	// returns a copy of the stored record and whether a live instance was
124	// overwritten.
125	func (r *registry) register(inst *instance, now time.Time) (instance, bool) {
126		r.mu.Lock()
127		defer r.mu.Unlock()
128		inst.token = newLeaseToken()
129		inst.expiresAt = now.Add(time.Duration(inst.TTLSeconds) * time.Second)
130		byName, ok := r.instances[inst.Service]
131		if !ok {
132			byName = make(map[string]*instance)
133			r.instances[inst.Service] = byName
134		}
135		overwritten := false
136		if prev, ok := byName[inst.Instance]; ok {
137			if prev.live(now) {
138				overwritten = true
139			}
140			// The replacement is a new instance: permits granted against the
141			// previous record stop being releasable and free its quota at once.
142			r.invalidatePermitsLocked(prev)
143		}
144		byName[inst.Instance] = inst
145		return *inst, overwritten
146	}
147	
148	// renew extends the lease of a live instance whose current token matches.
149	func (r *registry) renew(service, name, token string, now time.Time) error {
150		r.mu.Lock()
151		defer r.mu.Unlock()
152		inst := r.lookupLocked(service, name, now)
153		if inst == nil {
154			return errNotFound
155		}
156		if token == "" || token != inst.token {
157			return errLeaseConflict
158		}
159		inst.expiresAt = now.Add(time.Duration(inst.TTLSeconds) * time.Second)
160		return nil
161	}
162	
163	// reportHealth applies one health report to a live instance. bodyOK reports
164	// whether the request body decoded and validated; it is checked only after
165	// existence, token and policy so those errors take precedence. Reports never
166	// extend the lease. Sequence handling: a strictly larger sequence advances
167	// state; the same sequence with the same status is an idempotent no-op, with
168	// a different status a conflict; a smaller sequence is stale.
169	func (r *registry) reportHealth(service, name, token string, bodyOK bool, seq int64, pass bool, now time.Time) error {
170		r.mu.Lock()
171		defer r.mu.Unlock()
172		inst := r.lookupLocked(service, name, now)
173		if inst == nil {
174			return errNotFound
175		}
176		if token == "" || token != inst.token {
177			return errLeaseConflict
178		}
179		if !inst.health.configured {
180			return errHealthDisabled
181		}
182		if !bodyOK {
183			return errInvalidHealthReport
184		}
185		h := &inst.health
186		if h.hasSequence {
187			if seq < h.lastSequence {
188				return errStaleHealthReport
189			}
190			if seq == h.lastSequence {
191				if pass == h.lastStatusPass {
192					return nil
193				}
194				return errHealthReportConflict
195			}
196		}
197		h.hasSequence = true
198		h.lastSequence = seq
199		h.lastStatusPass = pass
200		if pass {
201			h.consecutivePass++
202			h.consecutiveFail = 0
203			if h.consecutivePass >= h.successThreshold {
204				h.status = healthHealthy
205			}
206		} else {
207			h.consecutiveFail++
208			h.consecutivePass = 0
209			if h.consecutiveFail >= h.failureThreshold {
210				h.status = healthUnhealthy
211			}
212		}
213		return nil
214	}
215	
216	// deregister removes a live instance whose current token matches.
217	func (r *registry) deregister(service, name, token string, now time.Time) error {
218		r.mu.Lock()
219		defer r.mu.Unlock()
220		inst := r.lookupLocked(service, name, now)
221		if inst == nil {
222			return errNotFound
223		}
224		if token == "" || token != inst.token {
225			return errLeaseConflict
226		}
227		r.invalidatePermitsLocked(inst)
228		delete(r.instances[service], name)
229		if len(r.instances[service]) == 0 {
230			delete(r.instances, service)
231		}
232		return nil
233	}
234	
235	// lookupLocked returns the live record or nil; expired records are treated as
236	// absent. Callers must hold r.mu.
237	func (r *registry) lookupLocked(service, name string, now time.Time) *instance {
238		inst := r.instances[service][name]
239		if inst == nil || !inst.live(now) {
240			return nil
241		}
242		return inst
243	}
244	
245	// snapshot returns copies of the live instances of service matching the
246	// version/zone filters (empty string disables a filter), sorted by instance
247	// name. Unhealthy instances are excluded from routing and discovery; only
248	// healthy or health-disabled instances appear. Copies are taken under the
249	// lock so callers can read them race-free.
250	func (r *registry) snapshot(service, version, zone string, now time.Time) []instance {
251		r.mu.Lock()
252		defer r.mu.Unlock()
253		var out []instance
254		for _, inst := range r.instances[service] {
255			if !inst.live(now) {
256				continue
257			}
258			if inst.health.configured && inst.health.status == healthUnhealthy {
259				continue
260			}
261			if version != "" && inst.Version != version {
262				continue
263			}
264			if zone != "" && inst.Zone != zone {
265				continue
266			}
267			out = append(out, *inst)
268		}
269		sort.Slice(out, func(a, b int) bool { return out[a].Instance < out[b].Instance })
270		return out
271	}
272	
273	// dropPermitLocked removes one permit and releases the quota it occupied on
274	// its instance. Callers must hold r.mu.
275	func (r *registry) dropPermitLocked(p *permit) {
276		delete(r.permits, p.token)
277		if n := r.inUse[p.inst] - 1; n > 0 {
278			r.inUse[p.inst] = n
279		} else {
280			delete(r.inUse, p.inst)
281		}
282	}
283	
284	// prunePermitsLocked discards every permit that is no longer valid at now:
285	// permits past their own expiry and permits bound to an instance whose lease
286	// has expired. Overwritten and deregistered instances are removed eagerly by
287	// their callers. Callers must hold r.mu.
288	func (r *registry) prunePermitsLocked(now time.Time) {
289		for token, p := range r.permits {
290			if !now.Before(p.expiresAt) || !p.inst.live(now) {
291				delete(r.permits, token)
292				if n := r.inUse[p.inst] - 1; n > 0 {
293					r.inUse[p.inst] = n
294				} else {
295					delete(r.inUse, p.inst)
296				}
297			}
298		}
299	}
300	
301	// invalidatePermitsLocked releases every outstanding permit bound to inst.
302	// Overwriting or deregistering an instance invalidates its old permits
303	// immediately and gives the quota back. Callers must hold r.mu.
304	func (r *registry) invalidatePermitsLocked(inst *instance) {
305		for token, p := range r.permits {
306			if p.inst != inst {
307				continue
308			}
309			delete(r.permits, token)
310			if n := r.inUse[inst] - 1; n > 0 {
311				r.inUse[inst] = n
312			} else {
313				delete(r.inUse, inst)
314			}
315		}
316	}
317	
318	// acquiredPermit is the result of a successful admission: a copy of the
319	// chosen instance together with the opaque token and its expiry.
320	type acquiredPermit struct {
321		inst      instance
322		token     string
323		expiresAt time.Time
324	}
325	
326	// acquire atomically selects an instance for key and occupies one permit
327	// slot on it. Candidates are the live, non-unhealthy instances of service
328	// matching the version/zone filters, ranked by the same weighted rendezvous
329	// score used by resolve, best first; the first-ranked candidate with a free
330	// slot wins. Unbounded instances (MaxConcurrency == 0) always admit. The
331	// lookup and the occupancy happen under one lock, so the number of valid
332	// permits can never exceed an instance's quota. It returns
333	// errNoRoutableInstance when the filter matches nothing and
334	// errConcurrencyLimited when every match is at capacity.
335	func (r *registry) acquire(service, key, version, zone string, ttl time.Duration, now time.Time) (acquiredPermit, error) {
336		r.mu.Lock()
337		defer r.mu.Unlock()
338		r.prunePermitsLocked(now)
339	
340		var candidates []*instance
341		for _, inst := range r.instances[service] {
342			if !inst.live(now) {
343				continue
344			}
345			if inst.health.configured && inst.health.status == healthUnhealthy {
346				continue
347			}
348			if version != "" && inst.Version != version {
349				continue
350			}
351			if zone != "" && inst.Zone != zone {
352				continue
353			}
354			candidates = append(candidates, inst)
355		}
356		if len(candidates) == 0 {
357			return acquiredPermit{}, errNoRoutableInstance
358		}
359		// Rank by descending rendezvous score; the instance name breaks the
360		// measure-zero tie exactly as selectInstance does.
361		sort.Slice(candidates, func(a, b int) bool {
362			sa := rendezvousScore(key, candidates[a].Instance, candidates[a].Weight)
363			sb := rendezvousScore(key, candidates[b].Instance, candidates[b].Weight)
364			if sa != sb {
365				return sa > sb
366			}
367			return candidates[a].Instance < candidates[b].Instance
368		})
369	
370		var chosen *instance
371		for _, cand := range candidates {
372			if cand.MaxConcurrency == 0 || r.inUse[cand] < cand.MaxConcurrency {
373				chosen = cand
374				break
375			}
376		}
377		if chosen == nil {
378			return acquiredPermit{}, errConcurrencyLimited
379		}
380	
381		token := newPermitToken()
382		for {
383			if _, taken := r.permits[token]; !taken {
384				break
385			}
386			token = newPermitToken()
387		}
388		expiresAt := now.Add(ttl)
389		r.permits[token] = &permit{
390			token:     token,
391			service:   service,
392			inst:      chosen,
393			expiresAt: expiresAt,
394		}
395		r.inUse[chosen]++
396		return acquiredPermit{inst: *chosen, token: token, expiresAt: expiresAt}, nil
397	}
398	
399	// release releases a valid permit granted for service. Unknown tokens,
400	// expired permits, tokens bound to another service and permits invalidated
401	// by overwrite, deregistration or lease expiry all return errPermitNotFound.
402	func (r *registry) release(service, token string, now time.Time) error {
403		r.mu.Lock()
404		defer r.mu.Unlock()
405		r.prunePermitsLocked(now)
406		p, ok := r.permits[token]
407		if !ok || p.service != service {
408			return errPermitNotFound
409		}
410		r.dropPermitLocked(p)
411		return nil
412	}
