13	
14	// leaseHeader carries the lease token on heartbeat and deregister requests.
15	const leaseHeader = "X-Meshcore-Lease"
16	
17	// namePattern constrains service and instance names: 1-64 ASCII letters,
18	// digits, dots, underscores or hyphens.
19	var namePattern = regexp.MustCompile(`^[A-Za-z0-9._-]{1,64}$`)
20	
21	func validName(s string) bool { return namePattern.MatchString(s) }
22	
23	type healthPolicyRequest struct {
24		FailureThreshold *int `json:"failureThreshold"`
25		SuccessThreshold *int `json:"successThreshold"`
26	}
27	
28	type registerRequest struct {
29		Endpoint       string               `json:"endpoint"`
30		Version        string               `json:"version"`
31		Zone           string               `json:"zone"`
32		Weight         int                  `json:"weight"`
33		TTLSeconds     int                  `json:"ttlSeconds"`
34		Metadata       map[string]string    `json:"metadata"`
35		HealthPolicy   *healthPolicyRequest `json:"healthPolicy"`
36		MaxConcurrency *int                 `json:"maxConcurrency"`
37	}
38	
39	func (r *registerRequest) valid() bool {
40		if r.Endpoint == "" || r.Version == "" || r.Zone == "" {
41			return false
42		}
43		if r.Weight < 1 || r.Weight > 100 || r.TTLSeconds < 1 || r.TTLSeconds > 300 {
44			return false
45		}
46		if r.MaxConcurrency != nil && (*r.MaxConcurrency < 1 || *r.MaxConcurrency > 10000) {
47			return false
48		}
49		for k, v := range r.Metadata {
50			if k == "" || v == "" {
51				return false
52			}
53		}
54		if r.HealthPolicy != nil {
55			p := r.HealthPolicy
56			if p.FailureThreshold == nil || p.SuccessThreshold == nil {
57				return false
58			}
59			if *p.FailureThreshold < 1 || *p.FailureThreshold > 10 ||
60				*p.SuccessThreshold < 1 || *p.SuccessThreshold > 10 {
61				return false
62			}
63		}
64		return true
65	}
66	
67	// instanceView is the public representation of a registered instance. The
68	// lease token is deliberately excluded; it only appears in registerResponse.
69	// MaxConcurrency is omitted for instances registered without a cap, where
70	// concurrency is unbounded.
71	type instanceView struct {
72		Service        string            `json:"service"`
73		Instance       string            `json:"instance"`
74		Endpoint       string            `json:"endpoint"`
75		Version        string            `json:"version"`
76		Zone           string            `json:"zone"`
77		Weight         int               `json:"weight"`
78		TTLSeconds     int               `json:"ttlSeconds"`
79		Metadata       map[string]string `json:"metadata"`
80		ExpiresAt      string            `json:"expiresAt"`
81		HealthStatus   string            `json:"healthStatus"`
82		MaxConcurrency int               `json:"maxConcurrency,omitempty"`
83	}
84	
85	func viewOf(inst instance) instanceView {
86		return instanceView{
87			Service:        inst.Service,
88			Instance:       inst.Instance,
89			Endpoint:       inst.Endpoint,
90			Version:        inst.Version,
91			Zone:           inst.Zone,
92			Weight:         inst.Weight,
93			TTLSeconds:     inst.TTLSeconds,
94			Metadata:       inst.Metadata,
95			ExpiresAt:      inst.expiresAt.UTC().Format(time.RFC3339),
96			HealthStatus:   inst.healthStatus(),
97			MaxConcurrency: inst.MaxConcurrency,
98		}
99	}
100	
101	type registerResponse struct {
102		instanceView
103		LeaseToken string `json:"leaseToken"`
104	}
105	
106	type discoveryResponse struct {
107		Service   string         `json:"service"`
108		Instances []instanceView `json:"instances"`
109	}
110	
111	type resolveResponse struct {
112		Service  string       `json:"service"`
113		Key      string       `json:"key"`
114		Instance instanceView `json:"instance"`
115	}
116	
117	func writeJSON(w http.ResponseWriter, status int, v any) {
118		w.Header().Set("Content-Type", "application/json; charset=utf-8")
119		w.WriteHeader(status)
120		_ = json.NewEncoder(w).Encode(v)
121	}
122	
123	func writeError(w http.ResponseWriter, status int, code string) {
124		writeJSON(w, status, map[string]any{"error": map[string]string{"code": code}})
125	}
126	
127	// handleInstance serves /v1/services/{service}/instances/{instance}.
128	func (s *server) handleInstance(w http.ResponseWriter, r *http.Request) {
129		switch r.Method {
130		case http.MethodPut:
131			s.register(w, r)
132		case http.MethodDelete:
133			s.deregister(w, r)
134		default:
135			w.Header().Set("Allow", "PUT, DELETE")
136			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
137		}
138	}
139	
140	func (s *server) register(w http.ResponseWriter, r *http.Request) {
141		service, name := r.PathValue("service"), r.PathValue("instance")
142		if !validName(service) || !validName(name) {
143			writeError(w, http.StatusBadRequest, "validation_error")
144			return
145		}
146		var req registerRequest
147		dec := json.NewDecoder(http.MaxBytesReader(w, r.Body, 1<<20))
148		dec.DisallowUnknownFields()
149		if err := dec.Decode(&req); err != nil || dec.Decode(&struct{}{}) != io.EOF || !req.valid() {
150			writeError(w, http.StatusBadRequest, "validation_error")
151			return
152		}
153		metadata := make(map[string]string, len(req.Metadata))
154		for k, v := range req.Metadata {
155			metadata[k] = v
156		}
157		inst := &instance{
158			Service:    service,
159			Instance:   name,
160			Endpoint:   req.Endpoint,
161			Version:    req.Version,
162			Zone:       req.Zone,
163			Weight:     req.Weight,
164			TTLSeconds: req.TTLSeconds,
165			Metadata:   metadata,
166		}
167		if req.MaxConcurrency != nil {
168			inst.MaxConcurrency = *req.MaxConcurrency
169		}
170		if p := req.HealthPolicy; p != nil {
171			inst.health = healthState{
172				configured:       true,
173				failureThreshold: *p.FailureThreshold,
174				successThreshold: *p.SuccessThreshold,
175				status:           healthHealthy,
176			}
177		}
178		stored, overwritten := s.registry.register(inst, s.now())
179		status := http.StatusCreated
180		if overwritten {
181			status = http.StatusOK
182		}
183		writeJSON(w, status, registerResponse{instanceView: viewOf(stored), LeaseToken: stored.token})
184	}
185	
186	func (s *server) deregister(w http.ResponseWriter, r *http.Request) {
187		service, name := r.PathValue("service"), r.PathValue("instance")
188		if !validName(service) || !validName(name) {
189			writeError(w, http.StatusBadRequest, "validation_error")
190			return
191		}
192		err := s.registry.deregister(service, name, r.Header.Get(leaseHeader), s.now())
193		writeLeaseResult(w, err)
194	}
195	
196	// handleHeartbeat serves /v1/services/{service}/instances/{instance}/heartbeat.
197	func (s *server) handleHeartbeat(w http.ResponseWriter, r *http.Request) {
198		if r.Method != http.MethodPost {
199			w.Header().Set("Allow", http.MethodPost)
200			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
201			return
202		}
203		service, name := r.PathValue("service"), r.PathValue("instance")
204		if !validName(service) || !validName(name) {
205			writeError(w, http.StatusBadRequest, "validation_error")
206			return
207		}
208		err := s.registry.renew(service, name, r.Header.Get(leaseHeader), s.now())
209		writeLeaseResult(w, err)
210	}
211	
212	func writeLeaseResult(w http.ResponseWriter, err error) {
213		switch {
214		case err == nil:
215			w.WriteHeader(http.StatusNoContent)
216		case errors.Is(err, errNotFound):
217			writeError(w, http.StatusNotFound, "instance_not_found")
218		case errors.Is(err, errLeaseConflict):
219			writeError(w, http.StatusConflict, "lease_conflict")
220		default:
221			writeError(w, http.StatusInternalServerError, "internal_error")
222		}
223	}
224	
225	// healthReportRequest is the body of a health report. Pointers distinguish
226	// an absent field from a zero value; both fields are required.
227	type healthReportRequest struct {
228		Sequence *int64  `json:"sequence"`
229		Status   *string `json:"status"`
230	}
231	
232	// handleHealth serves /v1/services/{service}/instances/{instance}/health.
233	// Existence, lease token and policy checks run inside the registry under one
234	// lock so concurrent reports, heartbeats and deregistrations stay atomic;
235	// the body is decoded up front but its validation error is only surfaced
236	// after those checks, matching the documented error precedence.
237	func (s *server) handleHealth(w http.ResponseWriter, r *http.Request) {
238		if r.Method != http.MethodPost {
239			w.Header().Set("Allow", http.MethodPost)
240			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
241			return
242		}
243		service, name := r.PathValue("service"), r.PathValue("instance")
244		if !validName(service) || !validName(name) {
245			writeError(w, http.StatusBadRequest, "validation_error")
246			return
247		}
248		var req healthReportRequest
249		dec := json.NewDecoder(http.MaxBytesReader(w, r.Body, 1<<20))
250		dec.DisallowUnknownFields()
251		bodyOK := dec.Decode(&req) == nil && dec.Decode(&struct{}{}) == io.EOF &&
252			req.Sequence != nil && *req.Sequence >= 0 &&
253			req.Status != nil && (*req.Status == "pass" || *req.Status == "fail")
254		var seq int64
255		pass := false
256		if bodyOK {
257			seq = *req.Sequence
258			pass = *req.Status == "pass"
259		}
260		err := s.registry.reportHealth(service, name, r.Header.Get(leaseHeader), bodyOK, seq, pass, s.now())
261		switch {
262		case err == nil:
263			w.WriteHeader(http.StatusNoContent)
264		case errors.Is(err, errNotFound):
265			writeError(w, http.StatusNotFound, "instance_not_found")
266		case errors.Is(err, errLeaseConflict):
267			writeError(w, http.StatusConflict, "lease_conflict")
268		case errors.Is(err, errHealthDisabled):
269			writeError(w, http.StatusConflict, "health_check_disabled")
270		case errors.Is(err, errInvalidHealthReport):
271			writeError(w, http.StatusBadRequest, "validation_error")
272		case errors.Is(err, errHealthReportConflict):
273			writeError(w, http.StatusConflict, "health_report_conflict")
274		case errors.Is(err, errStaleHealthReport):
275			writeError(w, http.StatusConflict, "stale_health_report")
276		default:
277			writeError(w, http.StatusInternalServerError, "internal_error")
278		}
279	}
280	
281	// handleDiscovery serves /v1/discovery/{service}.
282	func (s *server) handleDiscovery(w http.ResponseWriter, r *http.Request) {
283		if r.Method != http.MethodGet {
284			w.Header().Set("Allow", http.MethodGet)
285			writeError(w, http.StatusMethodNotAllowed, "method_not_allowed")
286			return
287		}
288		service := r.PathValue("service")
289		if !validName(service) {
290			writeError(w, http.StatusBadRequest, "validation_error")
291			return
292		}
293		query, err := url.ParseQuery(r.URL.RawQuery)
294		if err != nil {
295			writeError(w, http.StatusBadRequest, "validation_error")
296			return
297		}
298		var version, zone string
