1	package server
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"net/http"
7		"net/http/httptest"
8		"sync"
9		"testing"
10		"time"
11	)
12	
13	func registerCapBody(endpoint, version, zone string, weight, ttl, maxConcurrency int) string {
14		return fmt.Sprintf(`{"endpoint":%q,"version":%q,"zone":%q,"weight":%d,"ttlSeconds":%d,"maxConcurrency":%d}`,
15			endpoint, version, zone, weight, ttl, maxConcurrency)
16	}
17	
18	func mustRegisterCap(t *testing.T, h http.Handler, service, name string, maxConcurrency int) registerResponse {
19		t.Helper()
20		code, resp := mustRegister(t, h, service, name,
21			registerCapBody("http://"+name+":1", "v1", "z1", 10, 300, maxConcurrency))
22		if code != http.StatusCreated {
23			t.Fatalf("register = %d, want 201 (body %+v)", code, resp)
24		}
25		return resp
26	}
27	
28	func acquireBody(key string, ttl int, extra string) string {
29		s := fmt.Sprintf(`{"key":%q,"permitTTLSeconds":%d`, key, ttl)
30		if extra != "" {
31			s += "," + extra
32		}
33		return s + "}"
34	}
35	
36	func doAcquire(t *testing.T, h http.Handler, service, body string) *httptest.ResponseRecorder {
37		t.Helper()
38		return do(t, h, http.MethodPost, "/v1/admission/"+service+"/acquire", body, nil)
39	}
40	
41	func acquireOK(t *testing.T, h http.Handler, service, body string) acquireResponse {
42		t.Helper()
43		rec := doAcquire(t, h, service, body)
44		if rec.Code != http.StatusCreated {
45			t.Fatalf("acquire = %d, want 201 (body %s)", rec.Code, rec.Body.String())
46		}
47		requireJSON(t, rec)
48		var resp acquireResponse
49		if err := json.Unmarshal(rec.Body.Bytes(), &resp); err != nil {
50			t.Fatalf("acquire response is not JSON: %v", err)
51		}
52		if resp.PermitToken == "" {
53			t.Fatal("permitToken is empty")
54		}
55		return resp
56	}
57	
58	func releasePermit(t *testing.T, h http.Handler, service, token string) *httptest.ResponseRecorder {
59		t.Helper()
60		return do(t, h, http.MethodDelete, "/v1/admission/"+service+"/permits/"+token, "", nil)
61	}
62	
63	func TestAcquireSuccessShape(t *testing.T) {
64		h := Handler()
65		mustRegisterCap(t, h, "svc", "i1", 2)
66	
67		before := time.Now()
68		resp := acquireOK(t, h, "svc", acquireBody("user-42", 30, ""))
69		if resp.Service != "svc" || resp.Key != "user-42" {
70			t.Fatalf("service/key not echoed: %+v", resp)
71		}
72		if resp.Instance.Instance != "i1" || resp.Instance.MaxConcurrency != 2 {
73			t.Fatalf("unexpected instance view: %+v", resp.Instance)
74		}
75		expiresAt, err := time.Parse(time.RFC3339, resp.ExpiresAt)
76		if err != nil {
77			t.Fatalf("expiresAt %q is not RFC3339: %v", resp.ExpiresAt, err)
78		}
79		if expiresAt.Before(before.Add(29*time.Second)) || expiresAt.After(time.Now().Add(31*time.Second)) {
80			t.Fatalf("expiresAt %s not ~30s in the future", expiresAt)
81		}
82		if len(resp.PermitToken) < 16 {
83			t.Fatalf("permitToken too short: %q", resp.PermitToken)
84		}
85	}
86	
87	func TestMaxConcurrencyViewOmitempty(t *testing.T) {
88		h := Handler()
89		// Without a cap the field is absent from every public representation.
90		mustRegister(t, h, "svc", "unbounded", registerBody("http://a:1", "v1", "z1", 10, 60))
91		mustRegisterCap(t, h, "svc", "capped", 7)
92	
93		hasRawField := func(body []byte) bool {
94			var raw map[string]json.RawMessage
95			if err := json.Unmarshal(body, &raw); err != nil {
96				t.Fatalf("body is not a JSON object: %v", err)
97			}
98			_, ok := raw["maxConcurrency"]
99			return ok
100		}
101	
102		// Registration view of an uncapped instance.
103		rec := do(t, h, http.MethodPut, "/v1/services/svc/instances/unbounded2",
104			registerBody("http://a:1", "v1", "z1", 10, 60), nil)
105		if hasRawField(rec.Body.Bytes()) {
106			t.Fatalf("register view leaks maxConcurrency: %s", rec.Body.String())
107		}
108	
109		// Discovery: inspect each instance object.
110		rec = do(t, h, http.MethodGet, "/v1/discovery/svc", "", nil)
111		var disc struct {
112			Instances []map[string]json.RawMessage `json:"instances"`
113		}
114		if err := json.Unmarshal(rec.Body.Bytes(), &disc); err != nil {
115			t.Fatalf("discovery not JSON: %v", err)
116		}
117		for _, inst := range disc.Instances {
118			var name string
119			_ = json.Unmarshal(inst["instance"], &name)
120			_, present := inst["maxConcurrency"]
121			if name == "unbounded" && present {
122				t.Fatalf("unbounded discovery view exposes maxConcurrency: %s", rec.Body.String())
123			}
124			if name == "capped" {
125				var n int
126				_ = json.Unmarshal(inst["maxConcurrency"], &n)
127				if n != 7 {
128					t.Fatalf("capped maxConcurrency = %d, want 7", n)
129				}
130			}
131		}
132	
133		// Resolve and acquire echo the same view; the chosen instance only
134		// carries the field when it is capped.
135		checkView := func(view map[string]json.RawMessage) {
136			var name string
137			_ = json.Unmarshal(view["instance"], &name)
138			_, present := view["maxConcurrency"]
139			if name == "unbounded" && present {
140				t.Fatalf("unbounded view of %s exposes maxConcurrency", name)
141			}
142			if name == "capped" {
143				var n int
144				_ = json.Unmarshal(view["maxConcurrency"], &n)
145				if n != 7 {
146					t.Fatalf("capped maxConcurrency = %d, want 7", n)
147				}
148			}
149		}
150		rec = do(t, h, http.MethodGet, "/v1/resolve/svc?key=k", "", nil)
151		var res struct {
152			Instance map[string]json.RawMessage `json:"instance"`
153		}
154		if err := json.Unmarshal(rec.Body.Bytes(), &res); err != nil {
155			t.Fatalf("resolve not JSON: %v", err)
156		}
157		checkView(res.Instance)
158	
159		rec = doAcquire(t, h, "svc", acquireBody("k", 60, ""))
160		var acq struct {
161			Instance map[string]json.RawMessage `json:"instance"`
162		}
163		if err := json.Unmarshal(rec.Body.Bytes(), &acq); err != nil {
164			t.Fatalf("acquire not JSON: %v", err)
165		}
166		checkView(acq.Instance)
167	}
