361	func TestUnhealthyGetsNoPermitsButKeepsCounting(t *testing.T) {
362		s := newServer()
363		now := time.Date(2026, 10, 3, 0, 0, 0, 0, time.UTC)
364		s.now = func() time.Time { return now }
365		h := s.handler()
366	
367		// a: cap 1, health policy flips on a single report; b exists in another
368		// version so v1-only filters prove there is no fallback.
369		regA := mustRegisterWithPolicyBody2(t, h, "svc", "a", "v1", 1, 1, 1)
370		mustRegister(t, h, "svc", "b", registerBody("http://b:1", "v2", "z1", 10, 300))
