391		if rec.Code != http.StatusServiceUnavailable || errorCode(t, rec) != "no_available_instance" {
392			t.Fatalf("acquire while unhealthy = %d (%s), want 503 no_available_instance", rec.Code, errorCode(t, rec))
393		}
394	
395		// a recovers but the held permit still occupies its only slot: 429.
396		if rec := reportHealth(t, h, "svc", "a", regA, `{"sequence":2,"status":"pass"}`); rec.Code != http.StatusNoContent {
397			t.Fatalf("pass report = %d, want 204", rec.Code)
398		}
399		rec = doAcquire(t, h, "svc", acquireBody(key, 60, `"version":"v1"`))
400		if rec.Code != http.StatusTooManyRequests || errorCode(t, rec) != "concurrency_limited" {
401			t.Fatalf("acquire after recovery = %d (%s), want 429 concurrency_limited (held permit still counts)", rec.Code, errorCode(t, rec))
402		}
403		// Release the held permit: admission works again.
404		if rec := releasePermit(t, h, "svc", held.PermitToken); rec.Code != http.StatusNoContent {
405			t.Fatalf("release = %d, want 204", rec.Code)
406		}
407		acquireOK(t, h, "svc", acquireBody(key, 60, `"version":"v1"`))
408	}
