559		created, limited := 0, 0
560		var wg sync.WaitGroup
561		for i := 0; i < 16; i++ {
562			wg.Add(1)
563			go func(i int) {
564				defer wg.Done()
565				for j := 0; j < 20; j++ {
566					rec := doAcquire(t, h, "svc", acquireBody(fmt.Sprintf("g-%d-k-%d", i, j), 300, ""))
567					mu.Lock()
568					switch rec.Code {
569					case http.StatusCreated:
570						created++
571					case http.StatusTooManyRequests:
572						limited++
573					default:
574						t.Errorf("acquire = %d, want 201 or 429", rec.Code)
575					}
576					mu.Unlock()
577				}
578			}(i)
579		}
580		wg.Wait()
581		if created != cap {
582			t.Fatalf("created = %d, want exactly %d (limited=%d)", created, cap, limited)
583		}
584		if created+limited != 320 {
585			t.Fatalf("created+limited = %d, want 320", created+limited)
586		}
587	}
588	
589	func TestAcquireTokenUniqueAndOpaque(t *testing.T) {
590		h := Handler()
591		mustRegister(t, h, "svc", "open", registerBody("http://a:1", "v1", "z1", 10, 300))
592		seen := map[string]bool{}
593		for i := 0; i < 25; i++ {
594			tok := acquireOK(t, h, "svc", acquireBody("k", 60, "")).PermitToken
595			if seen[tok] {
596				t.Fatalf("duplicate permit token %q", tok)
597			}
598			seen[tok] = true
599		}
